CREATE TABLE IF NOT EXISTS `duels` (`id` INT AUTO_INCREMENT PRIMARY KEY, `challenger_id` INT NOT NULL, `opponent_id` INT NOT NULL, `week_key` VARCHAR(16) NOT NULL, `status` ENUM('pending','active','finished') NOT NULL DEFAULT 'pending', `winner_id` INT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `decided_at` DATETIME NULL, CONSTRAINT `fk_duels_challenger` FOREIGN KEY (`challenger_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_duels_opponent` FOREIGN KEY (`opponent_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_duels_winner` FOREIGN KEY (`winner_id`) REFERENCES `users` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_duels_users ON `duels` (`challenger_id`, `opponent_id`, `status`);
